1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	const BLOCK_SIZE = 3;
55	const BLOCK_BASE_PREMIUM = 60;
56	
57	const countByType = (items: Item[]): Map<string, number> => {
58	  const counts = new Map<string, number>();
59	  for (const item of items) counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
60	
61	  return counts;
62	};
63	
64	const basePremiumForType = (type: string, count: number): number =>
65	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
66	
67	const policyBasePremium = (items: Item[]): number =>
68	  [...countByType(items)]
69	    .map(([type, count]) => basePremiumForType(type, count))
70	    .reduce((total, premium) => total + premium, 0);
71	
72	const CURSE_PERCENT = 50;
73	
74	// Percentages MUST go through this helper. Multiplying first and dividing by
75	// 100 afterwards keeps the arithmetic drift-free; the tempting `amount * 0.5`
76	// (or `* 1.1`) introduces binary-fraction error — 100 * 1.1 yields
77	// 110.00000000000001 — and since the spec rounds premiums UP at the very end
78	// that drift becomes a whole extra G.
79	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
80	
81	const HIGH_ENCHANTMENT_PERCENT = 30;
82	const HIGH_ENCHANTMENT_THRESHOLD = 5;
83	
84	// Each item-level surcharge is "a percentage of this item's base premium, or
85	// nothing at all", so the condition is the only part that varies.
86	const percentOfWhen = (applies: boolean, amount: number, percent: number): number =>
87	  applies ? percentOf(amount, percent) : 0;
88	
89	const itemSurcharge = (item: Item): number => {
90	  const base = BASE_PREMIUMS[item.type];
91	  const curseSurcharge = percentOfWhen(item.cursed === true, base, CURSE_PERCENT);
92	  const highEnchantmentSurcharge = percentOfWhen(
93	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
94	    base,
95	    HIGH_ENCHANTMENT_PERCENT,
96	  );
97	
98	  return curseSurcharge + highEnchantmentSurcharge;
99	};
100	
101	const itemSurcharges = (items: Item[]): number =>
102	  items.reduce((total, item) => total + itemSurcharge(item), 0);
103	
104	// Every modifier is a percentage of a base premium, and they are SUMMED rather
105	// than compounded: the spec's worked example reads
106	// "100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G",
107	// so the first-insurance 10 % is taken on the policy base, not on the
108	// curse-inflated amount.
109	const LOYALTY_PERCENT = 20;
110	const LOYALTY_THRESHOLD_YEARS = 2;
111	
112	const FOLLOW_UP_PERCENT = 15;
113	
114	const quote = ({ items }: QuoteStep, customer: Customer, isFollowUp: boolean): StepResult => {
115	  const policyBase = policyBasePremium(items);
116	
117	  // Surcharges add to the policy base, discounts subtract from it. Both are
118	  // percentages OF THE POLICY BASE (never of each other) — see the note above.
119	  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_PERCENT);
120	  const loyaltyDiscount = percentOfWhen(
121	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
122	    policyBase,
123	    LOYALTY_PERCENT,
124	  );
125	
126	  const followUpDiscount = percentOfWhen(isFollowUp, policyBase, FOLLOW_UP_PERCENT);
127	
128	  const surcharges = itemSurcharges(items) + firstInsuranceSurcharge;
129	  const discounts = loyaltyDiscount + followUpDiscount;
130	  const total = policyBase + surcharges - discounts + PROCESSING_FEE;
131	
132	  return { premium: Math.ceil(total) };
133	};
134	
135	const INSURANCE_VALUES: Record<string, number> = {
136	  sword: 1000,
137	  amulet: 600,
138	  staff: 800,
139	  potion: 400,
140	  rune: 250,
141	  moonstone: 250,
142	};
143	
144	const DEDUCTIBLE = 100;
145	const CAP_MULTIPLIER = 2;
146	
147	interface Policy {
148	  items: Item[];
149	  remainingCap: number;
150	}
151	
152	const openPolicy = (items: Item[]): Policy => ({
153	  items,
154	  remainingCap:
155	    CAP_MULTIPLIER * items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0),
156	});
157	
158	// Settling a claim both answers the step and moves the policy on: successive
159	// claims draw down the same cap. Rather than writing through the caller's
160	// Policy, `claim` returns the policy it leaves behind, so the depletion is
161	// visible at the one place that owns the registry.
162	// The claim-side enchantment threshold (8) is deliberately NOT the premium-side
163	// one (5): a sword can be enchanted enough to cost more to insure without being
164	// enchanted enough to have its damage halved.
165	const HALVED_REIMBURSEMENT_THRESHOLD = 8;
166	const HALVED_REIMBURSEMENT_PERCENT = 50;
167	
168	// The clause reduces the damage amount; the deductible is applied afterwards.
169	const reimbursement = (damage: Damage, item: Item): number => {
170	  const halved = (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_THRESHOLD;
171	
172	  return halved ? percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT) : damage.amount;
173	};
174	
175	const claim = (
176	  { incident }: ClaimStep,
177	  policy: Policy,
178	): { result: StepResult; policy: Policy } => {
179	  const payout = incident.damages.reduce((total, damage) => {
180	    const item = policy.items.find(({ type }) => type === damage.itemType) as Item;
181	
182	    return total + (reimbursement(damage, item) - DEDUCTIBLE);
183	  }, 0);
184	
185	  const remainingCap = policy.remainingCap - payout;
186	
187	  return { result: { payout, remainingCap }, policy: { ...policy, remainingCap } };
188	};
189	
190	// The follow-up discount is about contract number, so only quote steps count —
191	// interleaved claim steps must not make the next quote look like a follow-up.
192	const isFollowUpQuote = (steps: Step[], index: number): boolean =>
193	  steps.slice(0, index).some((earlier) => earlier.op === "quote");
194	
195	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
196	  // Policies opened by quote steps, keyed by the step index a later claim cites.
197	  // Claims draw the cap down, so this registry is the one piece of carried state.
198	  const policies = new Map<number, Policy>();
199	
200	  const results = steps.map((step, index) => {
201	    if (step.op === "quote") {
202	      policies.set(index, openPolicy(step.items));
203	
204	      return quote(step, customer, isFollowUpQuote(steps, index));
205	    }
206	
207	    const settled = claim(step, policies.get(step.policy) as Policy);
208	    policies.set(step.policy, settled.policy);
209	
210	    return settled.result;
211	  });
212	
213	  return { results };
214	};
